// Something is already active/completed and this is a genuinely new/different request --
// this node now runs whenever there's an active_node_id at all (see Needs Park Before New?,
// which used to gate on process_id -- that broke once a completed inquiry correctly nulls
// process_id via reset_process, since the NEXT related side-query still needs active_node_id
// as its parent). Only actually PAUSE a node that's still genuinely 'active' -- a node
// already 'completed' just gets read for its id as the new node's parent, not relabeled
// 'paused', which would misrepresent an already-answered inquiry as still waiting to be
// resumed. No form_state snapshot needed here -- intention_nodes[id] is the only copy that
// ever existed (kept current every turn by Compute Form Outcome/Compute Execution Outcome),
// not a mirror of a root-level working copy.
const base = $json;
const nodes = base.intention_nodes || {};
const activeNode = nodes[base.active_node_id];
const shouldPause = Boolean(activeNode) && activeNode.status === 'active';
const intentionNodes = shouldPause
  ? { ...nodes, [base.active_node_id]: { ...activeNode, status: 'paused' } }
  : nodes;

// The new intent's parent is the nearest still-open ancestor of whatever was active --
// walking past any node already terminal (completed or abandoned) in that chain, not just
// active_node_id itself. Without this, every side-query that finishes becomes the next
// one's parent (List Vendors -> List Items -> Get Item -> List Items, nesting one level
// deeper each time) instead of all fanning out as siblings under the paused node they
// actually interrupted. Same TERMINAL_STATUSES/walk shape as Compute Execution Outcome
// (sap-inquiry-execution.json), Compute Form Outcome (sap-process-form-filling.json),
// Classify & Store Error (error-parser.json), and Resolve Final State
// (batch-processing.json) -- keep all five in sync if this ever changes.
const TERMINAL_STATUSES = new Set(['completed', 'abandoned']);
const findOpenAncestor = (nodeId) => {
  let current = nodeId;
  while (current) {
    const node = nodes[current];
    if (!node) return null;
    if (!TERMINAL_STATUSES.has(node.status)) return current;
    current = node.parent_id;
  }
  return null;
};

return [{ json: {
  ...base,
  active_node_id: null,
  // One-shot signal for Context Update's Initialize Process: the new node's parent, so the
  // graph nests instead of flattening every interruption into a sibling root. null when
  // nothing was active to park, or when the whole ancestor chain was already completed.
  new_process_parent_id: findOpenAncestor(base.active_node_id),
  intention_nodes: intentionNodes,
} }];
